shellCommands.command:
/bin/bash -lc "cat > /tmp/moment-browser/check.mjs <<'EOF'
import {chromium} from 'playwright';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1440, height: 900}});
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5173');
const button = page.getByRole('button', {name: 'Показать уведомление'});
const toast = page.locator('[data-toast]');
await button.click();
await toast.waitFor({state: 'visible'});
await page.screenshot({path: '/tmp/moment-desktop.png'});
await toast.waitFor({state: 'detached', timeout: 6000});
await button.click();
await page.waitForTimeout(2000);
await button.click();
await page.waitForTimeout(2300);
if (await toast.count() "'!== 1) throw new Error('"'Repeated click did not restart toast');
await toast.waitFor({state: 'detached', timeout: 3000});
await button.focus();
await page.keyboard.press('Enter');
await toast.waitFor({state: 'visible'});
await page.getByRole('button', {name: 'Закрыть', exact: true}).click();
await toast.waitFor({state: 'detached'});
await page.setViewportSize({width: 375, height: 812});
await button.click();
await toast.waitFor({state: 'visible'});
await page.screenshot({path: '/tmp/moment-mobile.png', fullPage: true});
const dimensions = await page.evaluate(() => ({scroll: document.documentElement.scrollWidth, width: innerWidth}));
if (dimensions.scroll > dimensions.width) throw new Error('Horizontal overflow');
const buttonBox = await button.boundingBox();
const toastBox = await toast.boundingBox();
if (toastBox.y + toastBox.height > buttonBox.y) throw new Error('Toast overlaps trigger');
if (errors.length) throw new Error(errors.join('\\n'));
console.log('PASS: show, automatic dismissal, repeat-click timer reset, keyboard activation, manual close, mobile layout, no runtime errors.');
await browser.close();
EOF"
